input.command:
cd /workspace && cat README.md .gitignore; grep -rn "invoiceAmount\|reportAmount" --exclude-dir=node_modules . 
cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : ''; const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
cat >> checks/public.cjs <<'EOF'

const { formatAmount } = require('../.build/money');
for (const [cents, text] of [[0, '0.00'], [1, '0.01'], [99, '0.99'], [100, '1.00'], [123, '1.23'], [123456, '1234.56'], [-1, '-0.01'], [-100, '-1.00'], [-123456, '-1234.56']]) {
  assert.equal(formatAmount(cents), text);
}
assert.equal(renderInvoice('inv', 0), 'inv: $0.00');
assert.equal(renderInvoice('inv', -250), 'inv: $-2.50');
assert.equal(renderReport([{ id: 'z', cents: 500 }, { id: 'a', cents: -5 }, { id: 'm', cents: 0 }]), 'z,5.00\na,-0.05\nm,0.00');
for (const name of ['invoiceAmount', 'reportAmount']) {
  for (const mod of ['invoice', 'report', 'money']) assert.equal(name in require('../.build/' + mod), false);
}
EOF
rm -rf .build && tsc -p tsconfig.json && node checks/public.cjs && echo OK; ls .build; grep -rn "invoiceAmount\|reportAmount" src

